import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ArrowLeft, Box, Compass } from 'lucide-react';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { SiteScene, type SiteMarkerConfig, type SiteViewState } from '../../features/site/SiteScene';
import '../styles/precision-roam.css';

/**
 * 全屏漫游（`docs/project/ROAM-PLAN-A.md` §2 S4a + S5）。
 *
 * 与 `/map` 的「模型叠在地图上」不同，这里是**一个连续空间**：相机自由走，影像地面
 * 跟着相机视野流式补瓦片（`roam` 开关 → `GroundStreamer`），层级不受二维地图
 * `minZoom/maxZoom` 约束——屏幕上这米有多宽，就取哪一层的瓦片。
 *
 * 热点交接（S5）：点热点卡片 → 相机起飞（`TAKEOFF_MS`）→ 再切路由。两张卡：
 * 「进入设备」去 `/devices/:id`；「看这里全景」只在热点声明了 `panoramaId` 时出现。
 *
 * **退化**：`/roam` 不带参数时仍然是既有的 720yun 全景页（见 `AppPrecision.tsx`），
 * 只有 `?roam=plane` 才进这里——经典的路径一个字都没动。
 */
const TAKEOFF_MS = 1200;
/** 看过手势引导就记一笔，下次不再挡屏幕。 */
const GUIDE_KEY = 'museum.roam-guide.v1';

export interface RoamPageProps {
  /** 测试与旧 UI 共用：允许注入别的场景组件。 */
  SceneComponent?: typeof SiteScene;
}

export function RoamPage({ SceneComponent = SiteScene }: RoamPageProps) {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const { config } = useMuseumConfig();
  const site = config.siteModel;
  const [view, setView] = useState<SiteViewState>({ reset: 0, rotate: false, top: false });
  const [focus, setFocus] = useState<string | null>(null);
  const [ready, setReady] = useState(false);
  /**
   * 一次性手势引导：进来先告诉人「单指转、双指缩、点卡片起飞」。
   * 只显示一次（本机记住），顶部还有一个「?」可以再看。
   */
  const [guide, setGuide] = useState(() => {
    try { return window.localStorage.getItem(GUIDE_KEY) !== 'seen'; } catch { return true; }
  });
  const dismissGuide = useCallback(() => {
    setGuide(false);
    try { window.localStorage.setItem(GUIDE_KEY, 'seen'); } catch { /* 隐私模式：每次都会再提示一次，无妨 */ }
  }, []);

  /*
   * 影像地面用的是根地图的瓦片底图（与 `/site` 的 precision 视图同一个来源）。
   */
  const basemap = useMemo(
    () => (config.maps.find(map => !map.parentId) ?? config.maps[0])?.basemap,
    [config.maps],
  );

  const markers = useMemo<SiteMarkerConfig[]>(() => (site?.hotspots ?? []).map(hotspot => ({
    id: hotspot.id,
    label: hotspot.label,
    description: hotspot.description,
  })), [site]);

  const fly = useCallback((hotspotId: string) => {
    if (!ready) return;
    setFocus(hotspotId);
  }, [ready]);

  /** 起飞交接的落点：热点自己声明的目的地（`panoramaId` 缺省时退到设备页）。 */
  const land = useCallback((hotspotId: string) => {
    const hotspot = site?.hotspots.find(item => item.id === hotspotId);
    if (!hotspot) return;
    setFocus(null);
    if (params.get('to') === 'device' || !hotspot.panoramaId) {
      navigate(`/devices/${hotspot.deviceId}`);
      return;
    }
    /*
     * `/panorama/:pointId` 收的是**地图点位 id**（不是 `panoramas[].id`）。
     * 所以先找指向这张全景的点位；找不到也照直走——PanoramaPage 会兜到 `panoramas[0]`。
     */
    const point = config.maps
      .flatMap(map => map.points ?? [])
      .find(item => item.target.kind === 'panorama' && item.target.id === hotspot.panoramaId);
    navigate(`/panorama/${point?.id ?? hotspot.panoramaId}`);
  }, [config.maps, navigate, params, site]);

  // 起飞交接只做一次：`focus` 清空后不要再触发。
  const landedRef = useRef<string | null>(null);
  useEffect(() => { if (focus === null) landedRef.current = null; }, [focus]);

  if (!site) return <div className="precision-roam-empty">暂无场地模型</div>;

  return (
    <div className="precision-roam-plane" data-testid="roam-plane">
      <div className="roam-canvas">
        <SceneComponent
          site={site}
          markers={markers}
          view={view}
          basemap={basemap}
          roam
          takeoffMs={TAKEOFF_MS}
          focusHotspotId={focus}
          onReady={() => setReady(true)}
          onActivate={id => {
            if (landedRef.current === id) return;
            landedRef.current = id;
            land(id);
          }}
        />
      </div>

      <header className="roam-top">
        <button type="button" className="roam-back" aria-label="返回" onClick={() => navigate('/map')}>
          <ArrowLeft size={18} />
        </button>
        <h1>{site.name}</h1>
        <button
          type="button"
          className="roam-reset"
          aria-label="操作提示"
          title="操作提示"
          data-testid="roam-help"
          onClick={() => setGuide(true)}
        >
          ?
        </button>
        <button
          type="button"
          className="roam-reset"
          aria-label="回到场地全景"
          data-testid="roam-reset"
          onClick={() => setView(state => ({ ...state, reset: state.reset + 1 }))}
        >
          <Compass size={18} />
        </button>
      </header>

      {site.hotspots.length > 0 && (
        <section className="roam-hotspots" data-testid="roam-hotspots" aria-label="场地热点">
          {site.hotspots.map(hotspot => (
            <article key={hotspot.id} className="roam-hotspot" data-testid={`roam-hotspot-${hotspot.id}`}>
              <button type="button" className="roam-hotspot-main" onClick={() => fly(hotspot.id)}>
                <Box size={16} />
                <span>
                  <strong>{hotspot.label}</strong>
                  <em>{hotspot.panoramaId ? '起飞 · 走进全景' : '起飞 · 走进设备'}</em>
                </span>
              </button>
              <div className="roam-hotspot-actions">
                <button type="button" onClick={() => navigate(`/devices/${hotspot.deviceId}`)}>进入设备</button>
                {hotspot.panoramaId && (
                  <button
                    type="button"
                    data-testid={`roam-hotspot-panorama-${hotspot.id}`}
                    onClick={() => navigate(`/panorama/${hotspot.panoramaId}`)}
                  >
                    看这里全景
                  </button>
                )}
              </div>
            </article>
          ))}
        </section>
      )}

      {guide && (
        <button type="button" className="roam-guide" data-testid="roam-guide" onClick={dismissGuide}>
          <strong>这样逛这个场地</strong>
          <span>单指拖动 = 环视四周</span>
          <span>双指捏合 = 靠近 / 拉远</span>
          <span>点下方卡片 = 起飞到设备跟前，再进全景</span>
          <em>点任意处开始 · 顶部「?」可以再看</em>
        </button>
      )}
    </div>
  );
}
